1428	    auto W2 = expert_W2.reshape({num_experts, -1}).to(torch::kFloat32);     // [E, H]
1429	    auto b2 = expert_b2.reshape({num_experts, -1}).to(torch::kFloat32);     // [E, 1]
1430	    const int H = W1.size(1);
