1433	    // by routing_w [N, A], reduced over A. scalar_in [N] is the (broadcast) MLP
1434	    // input. Returns [N].
1435	    auto run_experts = [&](const torch::Tensor& expert_idx,       // [N, A] long
1436	                           const torch::Tensor& routing_w) {      // [N, A] float
1437	        const int64_t A = expert_idx.size(1);
1438	        auto flat = expert_idx.reshape({-1});                     // [N*A]
1439	        auto g_W1 = W1.index_select(0, flat).reshape({N, A, H});  // [N,A,H]
1440	        auto g_b1 = b1.index_select(0, flat).reshape({N, A, H});
1441	        auto g_W2 = W2.index_select(0, flat).reshape({N, A, H});
1442	        auto g_b2 = b2.index_select(0, flat).reshape({N, A});     // [N,A]
1443	        auto si   = scalar_in.reshape({N, 1, 1});                 // [N,1,1]
1444	        auto hidden = (g_W1 * si + g_b1).clamp_min(0.0f);         // [N,A,H] ReLU
1445	        auto out    = (g_W2 * hidden).sum(2) + g_b2;              // [N,A]
1446	        return (out * routing_w).sum(1);                          // [N]
1447	    };
1448	
1449	    torch::Tensor out;
1450	    torch::Tensor count_idx;   // [N*A] long, for activation counting
1451	    if (prod_keys_A.defined() && prod_keys_A.numel() > 0 &&
1452	        peer_query_Ws.defined() && peer_query_Ws.numel() >= d_model) {
1453	        auto qw = peer_query_Ws.reshape({-1, d_model}).to(torch::kFloat32);  // [Q, d_model]
1454	        auto query = feat.matmul(qw.transpose(0, 1));                        // [N, Q]
1455	        const int Q = query.size(1);
1456	        const int half = Q / 2 > 0 ? Q / 2 : Q;
1457	        auto qa = query.narrow(1, 0, half);
1458	        auto A = prod_keys_A.reshape({-1, half}).to(torch::kFloat32);        // [na, half]
1459	        auto sa = qa.matmul(A.transpose(0, 1));                              // [N, na]
1460	        int na = A.size(0);
1461	        const double T = 10.0;   // gate temperature (matches adjoint PEER head)
1462	
1463	        if (prod_keys_B.defined() && prod_keys_B.numel() > 0 && Q - half > 0) {
1464	            auto qb = query.narrow(1, half, Q - half);
1465	            auto B = prod_keys_B.reshape({-1, Q - half}).to(torch::kFloat32);
1466	            auto sb = qb.matmul(B.transpose(0, 1));                          // [N, nb]
1467	            int nb = B.size(0);
1468	            const int ka = std::min<int>(std::max(peer_topk, 1), na);
1469	            const int kb = std::min<int>(std::max(peer_topk, 1), nb);
1470	            auto ta = sa.topk(ka, -1);  // vals,idx  [N, ka]
1471	            auto tb = sb.topk(kb, -1);  // vals,idx  [N, kb]
1472	            auto top_a_vals = std::get<0>(ta), top_a_idx = std::get<1>(ta);
1473	            auto top_b_vals = std::get<0>(tb), top_b_idx = std::get<1>(tb);
1474	            auto soft_a = torch::softmax(top_a_vals * T, -1);                // [N, ka]
1475	            auto soft_b = torch::softmax(top_b_vals * T, -1);
1476	            // k_a × k_b Cartesian product of candidate experts + routing weights.
1477	            auto expert_idx = (top_a_idx.unsqueeze(2) * nb + top_b_idx.unsqueeze(1))
1478	                                  .reshape({N, ka * kb})
1479	                                  .clamp(0, num_experts - 1);               // [N, A]
1480	            auto routing_w = (soft_a.unsqueeze(2) * soft_b.unsqueeze(1))
1481	                                  .reshape({N, ka * kb});                   // [N, A]
1482	            out = run_experts(expert_idx, routing_w);
1483	            count_idx = expert_idx.reshape({-1});
1484	        } else {
1485	            // Single sub-codebook: top-k over A directly.
1486	            const int ka = std::min<int>(std::max(peer_topk, 1), na);
1487	            auto ta = sa.topk(ka, -1);
1488	            auto top_a_vals = std::get<0>(ta), top_a_idx = std::get<1>(ta);
1489	            auto soft_a = torch::softmax(top_a_vals * T, -1);               // [N, ka]
1490	            auto expert_idx = top_a_idx.clamp(0, num_experts - 1);          // [N, ka]
1491	            out = run_experts(expert_idx, soft_a);
1492	            count_idx = expert_idx.reshape({-1});
1493	        }
1494	    } else {
1495	        // No product keys → single shared expert (index 0), weight 1.
1496	        auto expert_idx = torch::zeros({N, 1}, lopt);
1497	        auto routing_w  = torch::ones({N, 1},
1498	            torch::TensorOptions().dtype(torch::kFloat32).device(feat.device()));
1499	        out = run_experts(expert_idx, routing_w);
1500	        count_idx = expert_idx.reshape({-1});
1501	    }
1502	
1503	    // Update expert activation counts (best-effort; reused by recycling). Now
1504	    // counts every selected expert in the top-k combination, not just one.
1505	    if (expert_counts.defined() && expert_counts.numel() >= num_experts) {
1506	        auto counts = torch::zeros({num_experts}, lopt);
1507	        counts.scatter_add_(0, count_idx, torch::ones_like(count_idx));
1508	        expert_counts.add_(counts.to(expert_counts.dtype()));
1509	    }
1510	    (void)H; (void)expert_hidden;
1511	    return out;  // [N] float
1512	}
